}

function throttle(fn, limitMs = 150) {
  let waiting = false;
  return (...args) => {
    if (waiting) return;
    fn(...args); waiting = true;
    setTimeout(() => { waiting = false; }, limitMs);
  };
}

function connectWs(url, onMessage, delay = 1000) {
  const ws = new WebSocket(url);
  ws.onmessage = (e) => onMessage(JSON.parse(e.data));
  ws.onclose = () => setTimeout(() => connectWs(url, onMessage, Math.min(delay * 2, 30000)), delay);
  return ws;
}

import time, functools

def retry(times=3, delay=1.0):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try: return func(*args, **kwargs)
                except Exception:
                    if attempt == times: raise
                    time.sleep(delay * (2 ** (attempt - 1)))
        return wrapper
    return decorator

